
.ck-card {
  width: 100%;
  max-width: 680px;
  margin: 6px auto;
  background: var(--c-surface);
  border: 2px solid var(--c-border);
  border-radius: 12px;
  overflow: hidden;
  font-size: 13px;
  box-shadow: 0 3px 12px rgba(43, 45, 66, 0.12);
}

.ck-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 14px;
  background: linear-gradient(135deg, var(--c-primary) 0%, var(--c-primary-dark) 100%);
  color: #fff;
  .ck-title { font-weight: 800; font-size: 0.9rem; i { margin-right: 6px; } }
  .ck-count { font-size: 0.8rem; opacity: 0.92; }
}

.ck-body {
  padding: 14px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  &.stack { gap: 14px; }
  &.empty { color: var(--c-muted); font-style: italic; text-align: center; padding: 18px; }
}

.ck-item {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding-bottom: 10px;
  border-bottom: 1px dashed var(--c-border);
  &:last-child { border-bottom: none; padding-bottom: 0; }
}

.ck-result-row {
  display: flex;
  align-items: center;
  gap: 14px;
  flex-wrap: wrap;
}

.ck-die {
  display: flex;
  flex-direction: column;
  align-items: center;
  .die-label { font-size: 0.68rem; color: var(--c-muted); }
  .die-value {
    font-family: var(--font-num);
    font-size: 2rem;
    font-weight: 800;
    line-height: 1.2;
  }
}

.ck-target {
  display: flex;
  flex-direction: column;
  align-items: center;
  .target-label { font-size: 0.68rem; color: var(--c-muted); }
  .target-value { font-family: var(--font-num); font-size: 1.4rem; font-weight: 700; }
}

.ck-verdict {
  flex: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  font-size: 1.1rem;
  font-weight: 800;
  padding: 8px 14px;
  border-radius: 10px;
  i { font-size: 1rem; }
}

.crit {
  color: #fff;
  background: linear-gradient(135deg, #d4a017, #b8860b);
  box-shadow: 0 0 0 3px rgba(212, 160, 23, 0.25);
}
.succ { color: #fff; background: var(--c-success); }
.fail { color: #fff; background: #9a8f80; }
.fumble { color: #fff; background: var(--c-danger); }
.neu { color: var(--c-primary-dark); background: var(--c-track); }

.ck-sub {
  display: flex;
  align-items: center;
  gap: 8px;
  .ck-name { font-weight: 700; color: var(--c-primary-dark); }
  .ck-type {
    font-size: 0.72rem;
    padding: 2px 8px;
    border-radius: 6px;
    background: var(--c-track);
    color: var(--c-muted);
  }
  .ck-stage-badge {
    font-size: 0.72rem;
    padding: 2px 8px;
    border-radius: 6px;
    background: var(--c-primary);
    color: #fff;
  }
}

.ck-mod,
.ck-remark {
  font-size: 0.8rem;
  color: var(--c-muted);
  i { margin-right: 4px; color: var(--c-warning); }
}

.ck-stage {
  font-size: 0.8rem;
  color: var(--c-muted);
  i { margin-right: 4px; color: var(--c-warning); }
  .stage-chips {
    display: flex;
    gap: 6px;
    margin-top: 6px;
    flex-wrap: wrap;
  }
  .stage-chip {
    font-family: var(--font-num);
    font-size: 0.78rem;
    font-weight: 700;
    padding: 3px 10px;
    border-radius: 8px;
    &.pos { background: #e6f5ef; color: #1f6e42; }
    &.neg { background: #fbe9e4; color: #c0463f; }
    &.neu { background: var(--c-track); color: var(--c-muted); }
  }
  .stage-total {
    margin-top: 8px;
    font-size: 0.85rem;
    font-weight: 700;
    color: var(--c-primary-dark);
  }
}
